"about_items": [
{
"n": "#207·03",
"text": "This light grey woolen double-breasted coat features an English lapel and four dark buttons. The cut is tailored to highlight your defined waist, creating a structured yet feminine silhouette."
},
{
"n": "#369·32",
"text": "These graphite trousers are designed for walking but have a sleek profile that complements the smart occasion. The fabric appears smooth and matte, offering a refined look suitable for formal events."
},
{
"n": "#539·37",
"text": "This milky cashmere scarf displays a plaid pattern with soft fringes at the ends. Its gentle hue provides a warm contrast to the grey tones of your coat and blazer."
},
{
"n": "#156·38",
"text": "A classic burgundy leather handbag with two top handles and metal buckles. The deep red color adds an elegant pop against the neutral palette of your outfit."
},
{
"n": "#6·11",
"text": "This graphite blazer has a clean, modern cut with flap pockets and a single button closure. It provides additional structure to the ensemble while maintaining a slim fit that respects your waistline."
},
{
"n": "#363·05",
"text": "These chocolate-colored ankle boots feature a rounded toe and a zipper on the inner side. Their smooth leather finish ensures they match well with both your trousers and coat."
}
]
}
